301:  *----------------------------------------------------------------------------*/
302: /*
303:  * If any of hash field expiration command is called on a listpack hash object
304:  * for the first time, we convert it to OBJ_ENCODING_LISTPACK_EX encoding.
305:  * We allocate "struct listpackEx" which holds listpack pointer and metadata to
306:  * register key to the global DS. In the listpack, we append another TTL entry
307:  * for each field-value pair. From now on, listpack will have triplets in it:
308:  * field-value-ttl. If TTL is not set for a field, we store 'zero' as the TTL
309:  * value. 'zero' is encoded as two bytes in the listpack. Memory overhead of a
310:  * non-existing TTL will be two bytes per field.
311:  *
312:  * Fields in the listpack will be ordered by TTL. Field with the smallest expiry
313:  * time will be the first item. Fields without TTL will be at the end of the
314:  * listpack. This way, it is easier/faster to find expired items.
315:  */
316: 
317: #define HASH_LP_NO_TTL 0
318: 
319: struct listpackEx *listpackExCreate(void) {
320:     listpackEx *lpt = zcalloc(sizeof(*lpt));
321:     lpt->meta.trash = 1;
322:     lpt->lp = NULL;
323:     lpt->key = NULL;
324:     return lpt;
325: }
326: 
327: static void listpackExFree(listpackEx *lpt) {
328:     lpFree(lpt->lp);
329:     zfree(lpt);
330: }
331: 
332: /* Returns number of expired fields. */
333: static uint64_t listpackExExpireDryRun(const robj *o) {
334:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
335: 
336:     uint64_t expired = 0;
337:     unsigned char *fptr;
338:     listpackEx *lpt = o->ptr;
339: 
340:     fptr = lpFirst(lpt->lp);
341:     while (fptr != NULL) {
342:         long long val;
343: 
344:         fptr = lpNext(lpt->lp, fptr);
345:         serverAssert(fptr);
346:         fptr = lpNext(lpt->lp, fptr);
347:         serverAssert(fptr && lpGetIntegerValue(fptr, &val));
348: 
349:         if (!hashTypeIsExpired(o, val))
350:             break;
351: 
352:         expired++;
353:         fptr = lpNext(lpt->lp, fptr);
354:     }
355: 
356:     return expired;
357: }
358: 
359: /* Returns the expiration time of the item with the nearest expiration. */
360: static uint64_t listpackExGetMinExpire(robj *o) {
361:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
362: 
363:     long long expireAt;
364:     unsigned char *fptr;
365:     listpackEx *lpt = o->ptr;
366: 
367:     /* As fields are ordered by expire time, first field will have the smallest
368:      * expiry time. Third element is the expiry time of the first field */
369:     fptr = lpSeek(lpt->lp, 2);
370:     if (fptr != NULL) {
371:         serverAssert(lpGetIntegerValue(fptr, &expireAt));
372: 
373:         /* Check if this is a non-volatile field. */
374:         if (expireAt != HASH_LP_NO_TTL)
375:             return expireAt;
376:     }
377: 
378:     return EB_EXPIRE_TIME_INVALID;
379: }
380: 
381: /* Walk over fields and delete the expired ones. */
382: void listpackExExpire(robj *o, ExpireInfo *info) {
383:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK_EX);
384:     uint64_t min = EB_EXPIRE_TIME_INVALID;
385:     unsigned char *ptr, *field;
386:     listpackEx *lpt = o->ptr;
387: 
388:     ptr = lpFirst(lpt->lp);
389:     while (ptr != NULL && (info->itemsExpired < info->maxToExpire)) {
390:         long long val;
391: 
392:         field = ptr;
393:         ptr = lpNext(lpt->lp, ptr);
394:         serverAssert(ptr);
395:         ptr = lpNext(lpt->lp, ptr);
396:         serverAssert(ptr && lpGetIntegerValue(ptr, &val));
397: 
398:         /* Fields are ordered by expiry time. If we reached to a non-expired
399:          * field or a non-volatile field, we know rest is not yet expired. */
400:         if (val == HASH_LP_NO_TTL || (uint64_t) val > info->now)
401:             break;
402: 
403:         lpt->lp = lpDeleteRangeWithEntry(lpt->lp, &field, 3);
404:         ptr = field;
405:         info->itemsExpired++;
406:     }
407: 
408:     min = hashTypeGetNextTimeToExpire(o);
409:     info->nextExpireTime = (min != EB_EXPIRE_TIME_INVALID) ? min : 0;
410: }
