1546: void hashTypeConvertListpack(robj *o, int enc) {
1547:     serverAssert(o->encoding == OBJ_ENCODING_LISTPACK);
1548: 
1549:     if (enc == OBJ_ENCODING_LISTPACK) {
1550:         /* Nothing to do... */
1551: 
1552:     } else if (enc == OBJ_ENCODING_LISTPACK_EX) {
1553:         unsigned char *p;
1554: 
1555:         /* Append HASH_LP_NO_TTL to each field name - value pair. */
1556:         p = lpFirst(o->ptr);
1557:         while (p != NULL) {
1558:             p = lpNext(o->ptr, p);
1559:             serverAssert(p);
1560: 
1561:             o->ptr = lpInsertInteger(o->ptr, HASH_LP_NO_TTL, p, LP_AFTER, &p);
1562:             p = lpNext(o->ptr, p);
1563:         }
1564: 
1565:         listpackEx *lpt = listpackExCreate();
1566:         lpt->lp = o->ptr;
1567:         o->encoding = OBJ_ENCODING_LISTPACK_EX;
1568:         o->ptr = lpt;
1569:     } else if (enc == OBJ_ENCODING_HT) {
1570:         hashTypeIterator *hi;
1571:         dict *dict;
1572:         int ret;
1573: 
1574:         hi = hashTypeInitIterator(o);
1575:         dict = dictCreate(&mstrHashDictType);
1576: 
1577:         /* Presize the dict to avoid rehashing */
1578:         /* TODO: activeExpire list pack. Should be small */
1579:         dictExpand(dict,hashTypeLength(o, 0));
1580: 
1581:         while (hashTypeNext(hi, 0) != C_ERR) {
1582: 
1583:             hfield key = hashTypeCurrentObjectNewHfield(hi);
1584:             sds value = hashTypeCurrentObjectNewSds(hi,OBJ_HASH_VALUE);
1585:             dictUseStoredKeyApi(dict, 1);
1586:             ret = dictAdd(dict, key, value);
1587:             dictUseStoredKeyApi(dict, 0);
1588:             if (ret != DICT_OK) {
1589:                 hfieldFree(key); sdsfree(value); /* Needed for gcc ASAN */
1590:                 hashTypeReleaseIterator(hi);  /* Needed for gcc ASAN */
1591:                 serverLogHexDump(LL_WARNING,"listpack with dup elements dump",
1592:                     o->ptr,lpBytes(o->ptr));
1593:                 serverPanic("Listpack corruption detected");
1594:             }
1595:         }
1596:         hashTypeReleaseIterator(hi);
1597:         zfree(o->ptr);
1598:         o->encoding = OBJ_ENCODING_HT;
1599:         o->ptr = dict;
1600:     } else {
1601:         serverPanic("Unknown hash encoding");
1602:     }
1603: }
