1877: /* Return the next/minimum expiry time of the hash-field. This is useful if a
1878:  * field with the minimum expiry is deleted, and you want to get the next
1879:  * minimum expiry. Otherwise, consider using hashTypeGetMinExpire() which will
1880:  * be faster. If there is no field with expiry, returns EB_EXPIRE_TIME_INVALID */
1881: uint64_t hashTypeGetNextTimeToExpire(robj *o) {
1882:     if (o->encoding == OBJ_ENCODING_LISTPACK) {
1883:         return EB_EXPIRE_TIME_INVALID;
1884:     } else if (o->encoding == OBJ_ENCODING_LISTPACK_EX) {
1885:         return listpackExGetMinExpire(o);
1886:     } else {
1887:         serverAssert(o->encoding == OBJ_ENCODING_HT);
1888: 
1889:         dict *d = o->ptr;
1890:         if (!isDictWithMetaHFE(d))
1891:             return EB_EXPIRE_TIME_INVALID;
1892: 
1893:         dictExpireMetadata *expireMeta = (dictExpireMetadata *) dictMetadata(d);
1894:         return ebGetNextTimeToExpire(expireMeta->hfe, &hashFieldExpireBucketsType);
1895:     }
1896: }
