1898: /* Return the next/minimum expiry time of the hash-field.
1899:  * If not found, return EB_EXPIRE_TIME_INVALID */
1900: uint64_t hashTypeGetMinExpire(robj *o) {
1901:     ExpireMeta *expireMeta = NULL;
1902: 
1903:     if (o->encoding == OBJ_ENCODING_LISTPACK) {
1904:         return EB_EXPIRE_TIME_INVALID;
1905:     } else if (o->encoding == OBJ_ENCODING_LISTPACK_EX) {
1906:         listpackEx *lpt = o->ptr;
1907:         expireMeta = &lpt->meta;
1908:     } else {
1909:         serverAssert(o->encoding == OBJ_ENCODING_HT);
1910: 
1911:         dict *d = o->ptr;
1912:         if (!isDictWithMetaHFE(d))
1913:             return EB_EXPIRE_TIME_INVALID;
1914: 
1915:         expireMeta = &((dictExpireMetadata *) dictMetadata(d))->expireMeta;
1916:     }
1917: 
1918:     /* Keep aside next hash-field expiry before updating HFE DS. Verify it is not trash */
1919:     if (expireMeta->trash == 1)
1920:         return EB_EXPIRE_TIME_INVALID;
1921: 
1922:     return ebGetMetaExpTime(expireMeta);
1923: }
