1925: uint64_t hashTypeRemoveFromExpires(ebuckets *hexpires, robj *o) {
1926:     if (o->encoding == OBJ_ENCODING_LISTPACK) {
1927:         return EB_EXPIRE_TIME_INVALID;
1928:     } else if (o->encoding == OBJ_ENCODING_HT) {
1929:         /* If dict doesn't holds HFE metadata */
1930:         if (!isDictWithMetaHFE(o->ptr))
1931:             return EB_EXPIRE_TIME_INVALID;
1932:     }
1933: 
1934:     uint64_t expireTime = ebGetExpireTime(&hashExpireBucketsType, o);
1935: 
1936:     /* If registered in global HFE DS then remove it (not trash) */
1937:     if (expireTime != EB_EXPIRE_TIME_INVALID)
1938:         ebRemove(hexpires, &hashExpireBucketsType, o);
1939: 
1940:     return expireTime;
