1943: /* Add hash to global HFE DS and update key for notifications.
1944:  *
1945:  * key - must be the same instance that is stored in db->dict
1946:  */
1947: void hashTypeAddToExpires(redisDb *db, sds key, robj *hashObj, uint64_t expireTime) {
1948:     if (expireTime == EB_EXPIRE_TIME_INVALID)
1949:          return;
