660:      * if there are enough arguments we create a pre-sized hash, which
661:      * might over allocate memory if there are duplicates. */
662:     size_t new_fields = (end - start + 1) / 2;
663:     if (new_fields > server.hash_max_listpack_entries) {
664:         hashTypeConvert(o, OBJ_ENCODING_HT, &db->hexpires);
665:         dictExpand(o->ptr, new_fields);
